// Interviewer: Find two numbers in a sorted array that sum to a target

public Optional<int[]> findTwoSum(int[] nums, int target) {
    // "I'll use two pointers because the array is sorted."
    // "My reasoning: we can eliminate half the search space each step."
    var left = 0;
    var right = nums.length - 1;

    while (left < right) {
        var currentSum = nums[left] + nums[right];

        // "If sum is too high, I move right pointer left to decrease the sum."
        if (currentSum == target) {
            return Optional.of(new int[]{nums[left], nums[right]});
        } else if (currentSum > target) {
            right--; // "Trade-off: I'm assuming no duplicates matter."
        } else {
            left++;  // "If sum is too low, move left pointer right."
        }
    }

    return Optional.empty(); // "No pair found after full scan."
}

// Interviewer: Find the first non-repeating character in a string

// Plain-English explanation:
// "The algorithm does this: finds the first character that appears only once."
// "Step 1: I walk through the string once and count how many times each character appears."
// "Step 2: I walk through the string a second time and return the first character with count of 1."
// "The data structure I need is a HashMap to store character counts."
// "Does that make sense? Should I code it?"

public Optional<Character> firstNonRepeating(String input) {
    // Now coding the English explanation:
    var counts = new HashMap<Character, Integer>();

    // Step 1: Count occurrences
    for (var ch : input.toCharArray()) {
        counts.put(ch, counts.getOrDefault(ch, 0) + 1);
    }

    // Step 2: Find first with count 1
    for (var ch : input.toCharArray()) {
        if (counts.get(ch) == 1) {
            return Optional.of(ch);
        }
    }

    return Optional.empty();
}

