// Pattern 1: Single loop with constant-time operations
public boolean containsDuplicate(int[] nums) {
    var seen = new HashSet<Integer>();
    for (int num : nums) {  // O(n) - runs n times
        if (seen.contains(num)) return true;  // O(1) average lookup
        seen.add(num);  // O(1) average insert
    }
    return false;
}
// Verbal: "O(n) because the loop runs once per element, and both HashSet operations are O(1)"

// Pattern 2: Nested loops over same input
public int countPairs(int[] nums) {
    int count = 0;
    for (int i = 0; i < nums.length; i++) {  // Outer: n iterations
        for (int j = i + 1; j < nums.length; j++) {  // Inner: up to n iterations
            if (nums[i] + nums[j] == 10) count++;
        }
    }
    return count;  // Total: n * n = O(n²)
}
// Verbal: "O(n²) because for each element, we compare it with all remaining elements"
